  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 60);

const filename = slug + '-' + timestamp + '.png';
const r2_key = prefix + '/' + filename;

const result = {
  json: {
    filename,
    r2_key,
    r2_bucket: 'maxmorrys-lms',
    type: promptData.type,
    dimensions: promptData.dimensions,
    original_prompt: promptData.original_prompt,
    enhanced_prompt: promptData.prompt,
    for_workflow: promptData.for_workflow,
    context: promptData.context,
    slug: promptData.slug || slug,
    generated_at: now,
    id: promptData.id,
    blogPost_passthrough: promptData.blogPost_passthrough
  }
};
if (input.binary) result.binary = input.binary;
return result;

